    <td background="images/bg.gif"><font class=""><a href="modules.php?name=News&new_topic=14">Music</a></font><br><font class="testo_notizia" color="#000000"><b>[<a href="modules.php?name=&amp;file=categories&amp;op=newindex&amp;catid=3"><font class="esclusiva">Rumours</font></a>] Talking About Madonna's New Tracks.</b></font></td>
